# Code generated by Claude
"""
The inspection tool of the MPVI pipeline: everything between an instruction and the first motion, as a Markdown report. No simulator.

    python experiments/mpvi_trace.py "put the beaker on the hotplate" [--mode cache_only|cache_or_live|live] [--out FILE] [--side left]

From the stored replies by default (mode cache_only: no API call; a missing reply is reported in the trace). The report lists, in order: the planning request as sent (model, settings, prompt, JSON
schema), the raw reply, the parsed plan; the labeling request (prompt, schema), its raw reply, the parsed labels (primitive, object phrases with roles); the keyword cross-check per step (the words
found, the keyword primitive, the labeling's primitive, agreement, ambiguity, and whether stop_on_disagreement would stop); the computed tags (index, check, group) and the execution units with the
completion check that closes each; and a dry run of the grounding at dispatch time against the task's configuration (no simulator: the world model is src/world_model.StaticTaskSource, the hand
is simulated: a resolved pick puts the object in the hand, a resolved place empties it): each navigation target's stance, each manipulation step's resolved entries or its failure reason.
With --run DIR (a folder written by experiments/mpvi_text_test.py --out) the report ends with every completion check of that run: the triggering wrist camera's image (copied next to the report),
the prompt, the raw reply, the parsed verdict and the oracle's verdict (agree or disagree), and the outcome.

The report goes to docs/reports/<date>_<time>_trace_<slug>.md unless --out is given, and its path is printed.
"""

import argparse
import json
import re
import shutil
import sys
import time
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))

from src.grounding import make_grounder, make_operator, make_search_stub  # noqa: E402
from src.llm_gemini import GeminiCaller, LLMError  # noqa: E402
from src.mpvi_planner import PlannerError, make_llm_planner  # noqa: E402
from src.mpvi_postprocess import PostprocessError, keyword_primitive, make_llm_labeler, postprocess  # noqa: E402
from src.mpvi_schemas import Labels, Plan
from src.mpvi_vlm import parse_verdict  # noqa: E402
from src.orchestrator import CHECK_EVENT  # noqa: E402
from src.task_config import LLM_CFG  # noqa: E402
from src.world_model import StaticTaskSource, WorldModel  # noqa: E402


def cell(text):
    """Makes a text safe for a Markdown table cell."""
    return str(text).replace("|", "\\|").replace("\n", " ")


def fence(text, lang=""):
    """A fenced code block; the fence is longer than any run of backticks in the text (the planner's prompt has a fenced JSON example in it)."""
    ticks = "`" * max(3, max((len(m) for m in re.findall(r"`+", text)), default=0) + 1)
    return f"{ticks}{lang}\n{text}\n{ticks}\n"


def pretty(text):
    """Pretty-prints a JSON text if it is JSON, else gives it back."""
    try:
        return json.dumps(json.loads(text), indent=2, ensure_ascii=False)
    except (json.JSONDecodeError, TypeError):
        return text


def checks_section(head, out, run_dir, images_dir):
    """Describes the completion checks and the outcome of a run (from its summary.json, llm_log.json and vlm_images/).

    Args:
        head (callable): Starts a numbered section.
        out (list): The report lines; changed.
        run_dir (Path): A run folder written by experiments/mpvi_text_test.py (--out).
        images_dir (Path): Where the report's images are copied (linked relatively from the report).
    """
    head(f"Completion checks and outcome of the run `{run_dir.name}`")
    summ = json.loads((run_dir / "summary.json").read_text())
    log = json.loads((run_dir / "llm_log.json").read_text()) if (run_dir / "llm_log.json").is_file() else {"calls": []}
    vlm_calls = [c for c in log["calls"] if c["kind"] == "vlm"]
    out.append(f"Checker: `{summ.get('checker', 'oracle')}`; outcome **{summ.get('outcome')}**; plan failure: {summ.get('plan_failure')}; segment status: {summ.get('status')}\n")
    verdicts = summ.get("verdicts", [])
    if not verdicts:
        out.append("No check ran.\n")
        return
    images_dir.mkdir(parents=True, exist_ok=True)
    for n, v in enumerate(verdicts):
        d = v.get("details") or {}
        title = f"Check {n}: segment {v['segment']}, event `{v['event']}`, " + ("DECIDES" if v["decides"] else "logged only (the oracle's verdict, no VLM call)")
        out.append(f"### {title}\n")
        if "vlm" not in d:
            out.append(f"- oracle: {'PASS' if v['passed'] else 'FAIL'}" + (f" ({v['reason']})" if v["reason"] else "") + "\n")
            continue
        vlm, orc = d["vlm"], d["oracle"]
        call = next((c for c in vlm_calls if c.get("image_sha256") == vlm.get("image_sha256")), None)
        out.append(f"- camera `{vlm['camera']}` (the triggering gripper's wrist camera), prompt version `{vlm['prompt_version']}`, image SHA-256 `{str(vlm['image_sha256'])[:16]}`"
                   + (f", reply {'read from the cache' if call['from_cache'] else f'live ({call['seconds']:.1f} s, {call['attempts']} try(ies))'}" if call else "") + "\n")
        src = run_dir / "vlm_images" / f"{vlm['image_sha256']}.png"
        if vlm.get("image_sha256") and src.is_file():
            shutil.copy(src, images_dir / f"check{n}.png")
            out.append(f"![check {n}: {vlm['camera']}]({images_dir.name}/check{n}.png)\n")
        if call:
            out.append("Prompt:\n\n" + fence(call["prompt"]))
            out.append("Raw reply:\n\n" + fence(call["reply_text"]))
        parsed = parse_verdict(vlm["reply_text"]) if vlm.get("reply_text") is not None else None
        out.append(f"- parsed verdict: **{vlm['verdict']}**" + (" (UNPARSED: counted as NO)" if parsed and parsed[1] else "") + (f"; error: {vlm['error']}" if vlm.get("error") else ""))
        out.append(f"- oracle verdict: **{'PASS' if orc['passed'] else 'FAIL'}**" + (f" ({orc['reason']})" if orc["reason"] else ""))
        out.append(f"- VLM vs oracle: **{'agree' if d['agree'] else 'DISAGREE' if d['agree'] is False else 'no comparison'}**; the decision is the VLM's: {'PASS' if v['passed'] else 'FAIL'}\n")


def build_trace(instruction, mode, side, run_dir=None, images_dir=None):
    """Runs the pipeline up to the first motion and describes every step.

    Args:
        instruction (str): The task instruction.
        mode (str): The LLM mode (cache_only, cache_or_live, live).
        side (str): The manipulating hand for the grounding dry run.
        run_dir (Path or None): A run folder (experiments/mpvi_text_test.py --out) whose completion checks and outcome are added at the end.
        images_dir (Path or None): Where the check images are copied; required with run_dir.

    Returns:
        str: The Markdown report.
    """
    out = [f"# MPVI trace: {instruction!r}\n", f"Generated {time.strftime('%Y-%m-%d %H:%M:%S')} by experiments/mpvi_trace.py. No simulator. LLM mode `{mode}`, model `{LLM_CFG['model']}`.\n"]
    caller = GeminiCaller(mode=mode, say=lambda *_: None)
    S = {"plan": None, "tagged": None, "n": 0}

    def head(title):
        S["n"] += 1
        out.append(f"## {S['n']}. {title}\n")

    def calls_section(kind, title, model_cls):
        entries = [c for c in caller.log if c["kind"] == kind]
        if not entries:
            return
        c = entries[-1]
        head(f"{title} request, as sent")
        out.append(f"- model `{c['model']}`, prompt version `{c['version']}`, schema `{c['schema']}` (the Pydantic model's JSON schema, sent as `response_json_schema`)\n"
                   f"- temperature {LLM_CFG['temperature']}, thinking budget {LLM_CFG['thinking_budget']}, response MIME type `application/json`\n"
                   f"- cache key `{c['key'][:16]}`; this reply was {'read from the cache' if c['from_cache'] else f'live ({c['seconds']:.1f} s, {c['attempts']} try(ies))'}\n")
        out.append("Prompt:\n\n" + fence(c["prompt"]))
        out.append("JSON schema:\n\n" + fence(json.dumps(model_cls.model_json_schema(), indent=2), "json"))
        head(f"{title} reply, raw")
        out.append(fence(pretty(c["reply_text"]), "json"))

    # --- planning ---
    try:
        plan = make_llm_planner(caller.bind("plan", LLM_CFG["planner_prompt_version"]))(instruction)
    except (LLMError, PlannerError) as e:
        calls_section("plan", "Planning", Plan)
        out.append(f"## STOPPED at the planning call\n\n{type(e).__name__}: {e}\n")
        return "\n".join(out)
    calls_section("plan", "Planning", Plan)
    S["plan"] = plan
    head("Parsed plan")
    out.append(f"Task name: `{plan['task_name']}`\n")
    out.append("| # | type | description | completion criteria | target |\n|---|---|---|---|---|")
    out += [f"| {i} | {s['type']} | {cell(s['description'])} | {cell(s['completion_criteria'])} | {cell(s['target'])} |" for i, s in enumerate(plan["segments"])]
    out.append("")

    # --- labeling and post-processing (never stops on a disagreement here: the trace shows it) ---
    lines = []
    try:
        tagged = postprocess(plan, make_llm_labeler(caller.bind("label", LLM_CFG["label_prompt_version"])), stop_on_disagreement=False, say=lines.append)
    except (LLMError, PostprocessError) as e:
        calls_section("label", "Labeling", Labels)
        out.append(f"## STOPPED at the labeling call\n\n{type(e).__name__}: {e}\n")
        return "\n".join(out)
    calls_section("label", "Labeling", Labels)
    S["tagged"] = tagged
    segs = tagged["segments"]
    head("Parsed labels")
    out.append("| segment | description | primitive | object phrases (role) |\n|---|---|---|---|")
    out += [f"| {s['index']} | {cell(s['description'])} | {s['primitive']} | {cell('; '.join(f'{o['phrase']} ({o['role']})' for o in s['objects']))} |" for s in segs if s["type"] == "manipulation"]
    out.append("")

    # --- keyword cross-check ---
    head("Keyword cross-check, per manipulation step")
    out.append("Whole words anywhere in the description; pick up / pick-up / pick / grasp / grab = pick, place / put / set down = place; the LAST match wins. The labeling's answer is the one used; the keywords only log.\n")
    out.append("| segment | words found | keyword primitive | labeling primitive | agree | ambiguous |\n|---|---|---|---|---|---|")
    disagreements = 0
    for s in segs:
        if s["type"] != "manipulation":
            continue
        kw = keyword_primitive(s["description"])
        agree = "no keyword" if kw["primitive"] is None else ("yes" if kw["primitive"] == s["primitive"] else "NO")
        disagreements += agree == "NO"
        out.append(f"| {s['index']} | {cell(kw['matches'])} | {kw['primitive']} | {s['primitive']} | {agree} | {kw['ambiguous']} |")
    out.append("")
    out.append(f"Logged cases: {len(tagged['postprocess']['log'])}. With `stop_on_disagreement` ON the plan would " + ("STOP before it starts (a disagreement)." if disagreements else "run (no disagreement)."))
    out.append("")
    if lines:
        out.append(fence("\n".join(lines)))

    # --- tags and units ---
    head("Computed tags and execution units")
    out.append("`check` and `group` are plain code (the paper's rule: the last manipulation step before a navigation step, and the last step of the plan; consecutive manipulation steps are one unit).\n")
    out.append("| index | type | primitive | check | group |\n|---|---|---|---|---|")
    out += [f"| {s['index']} | {s['type']} | {s.get('primitive', '')} | {s['check']} | {s.get('group', '')} |" for s in segs]
    out.append("")
    groups = {}
    for s in segs:
        if s["type"] == "manipulation":
            groups.setdefault(s["group"], []).append(s)
    for g, members in groups.items():
        last = members[-1]
        ev = CHECK_EVENT.get(last["primitive"], "none (no primitive)")
        out.append(f"- Unit {g}: segments {[m['index'] for m in members]}; the completion criterion is the last step's: \"{last['completion_criteria']}\"; the check fires at the event `{ev}` of step {last['index']}.")
    out.append("")

    # --- grounding dry run ---
    head("Grounding, dry run at dispatch time")
    world = WorldModel([StaticTaskSource()])
    world.refresh(0.0)
    out.append("World model (the task's configuration; z is 0 here, there is no model to give the bench height):\n")
    out.append("| id | kind | phrases | position (m) | properties | found |\n|---|---|---|---|---|---|")
    out += [f"| {e.id} | {e.kind} | {cell(', '.join(e.phrases))} | ({e.position[0]:.2f}, {e.position[1]:.2f}) | {cell({k: v for k, v in e.properties.items() if k not in ('stance',)})} | {e.found} |" for e in world.entries()]
    out.append("")
    grounder = make_grounder(world, make_search_stub(), make_operator(), side)
    out.append(f"Manipulating hand: {side}. The hand is simulated (a resolved pick puts the object in it, a resolved place empties it). No operator is present; the search is the stub.\n")
    out.append("| segment | step | result |\n|---|---|---|")
    stopped = False
    for s in segs:
        if stopped:
            out.append(f"| {s['index']} | {cell(s['description'])} | not reached |")
            continue
        if s["type"] == "navigation":
            try:
                st = world.stance(s["target"])
                out.append(f"| {s['index']} | {cell(s['description'])} | target `{s['target']}` -> stance xy ({st['xy'][0]:.3f}, {st['xy'][1]:.3f}), yaw {st['yaw']:.2f}, pedestal {st['pedestal_q']} |")
            except KeyError as e:
                out.append(f"| {s['index']} | {cell(s['description'])} | STOPS: {cell(e.args[0])} |")
                stopped = True
            continue
        if s["primitive"] not in CHECK_EVENT:
            out.append(f"| {s['index']} | {cell(s['description'])} | STOPS: no primitive for this step |")
            stopped = True
            continue
        r = grounder["begin"](s)
        if r["state"] == "resolved":
            ids = {role: e.id for role, e in r["resolved"].items()}
            out.append(f"| {s['index']} | {cell(s['description'])} | resolved {cell(ids)} |")
            man = r["resolved"].get("manipulated")
            if man is not None:
                world.get(man.id).properties["held_by"] = side if s["primitive"] == "pick" else None
        else:
            out.append(f"| {s['index']} | {cell(s['description'])} | STOPS: {cell(r.get('reason', r['state']))} |")
            stopped = True
    out.append("")
    out.append("Grounding log:\n\n" + fence(json.dumps(grounder["log"], indent=1, default=str), "json"))
    out.append("Result: " + ("the plan would STOP in the grounding dry run (see the table)." if stopped else "every step grounds; the plan would reach the first motion.") + "\n")
    if run_dir is not None:
        checks_section(head, out, Path(run_dir), images_dir)
    return "\n".join(out)


def main():
    ap = argparse.ArgumentParser(description="Markdown trace of the MPVI pipeline from an instruction to the grounded steps (no simulator).")
    ap.add_argument("instruction")
    ap.add_argument("--mode", choices=("cache_only", "cache_or_live", "live"), default="cache_only")
    ap.add_argument("--out", help="the report file (default docs/reports/<date>_<time>_trace_<slug>.md)")
    ap.add_argument("--side", default="left", choices=("left", "right"))
    ap.add_argument("--run", help="a run folder written by experiments/mpvi_text_test.py --out: adds each completion check (image, prompt, raw reply, parsed verdict, oracle verdict) and the outcome")
    a = ap.parse_args()
    if a.out:
        path = Path(a.out)
    else:
        slug = re.sub(r"[^a-z0-9]+", "_", a.instruction.lower()).strip("_")[:40]
        path = PROJECT_ROOT / "docs" / "reports" / f"{time.strftime('%Y%m%d_%H%M')}_trace_{slug}.md"
    text = build_trace(a.instruction, a.mode, a.side, a.run, path.parent / f"{path.stem}_images")
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_suffix(".tmp")
    tmp.write_text(text)
    tmp.replace(path)
    print(path)


if __name__ == "__main__":
    main()
